import numpy as np
import ot

# Test what sinkhorn_log returns
n, m = 100, 80
C = np.random.rand(n, m)
a = np.ones(n)/n; b = np.ones(m)/m
result = ot.sinkhorn(a, b, C, 0.1, method='sinkhorn_log', log=True)
print('Type:', type(result))
if isinstance(result, tuple):
    print('Tuple len:', len(result))
    for i, r in enumerate(result):
        if hasattr(r, 'shape'): print(f'  [{i}]: shape={r.shape}')
        else: print(f'  [{i}]: {type(r)}')
" 2>&1"}

